import java.util.ArrayList;
import java.util.List;

class Order {
    // Inner private/package class representing tightly bound part
    static class OrderItem {
        private String sku;
        private int quantity;
        private double unitPrice;

        public OrderItem(String sku, int quantity, double unitPrice) {
            this.sku = sku;
            this.quantity = quantity;
            this.unitPrice = unitPrice;
        }

        public double getSubtotal() { return quantity * unitPrice; }
        public String getLine() { return sku + " (x" + quantity + ") @ $" + unitPrice + " = $" + getSubtotal(); }
    }

    private String orderId;
    private List<OrderItem> items = new ArrayList<>(); // Strong Has-A

    public Order(String orderId) {
        this.orderId = orderId;
    }

    // The Order manages the creation and lifecycle of OrderItems
    public void addLineItem(String sku, int qty, double price) {
        this.items.add(new OrderItem(sku, qty, price));
    }

    public double calculateTotal() {
        double total = 0;
        for (OrderItem item : items) total += item.getSubtotal();
        return total;
    }

    public void printReceipt() {
        System.out.println("=== Order Receipt: " + orderId + " ===");
        for (OrderItem item : items) {
            System.out.println(" - " + item.getLine());
        }
        System.out.println("Total Due: $" + calculateTotal());
    }
}

public class CompositionDemo {
    public static void main(String[] args) {
        Order order = new Order("ORD-2026-901");
        order.addLineItem("BOOK-JAVA", 2, 45.00);
        order.addLineItem("MUG-COFFEE", 1, 15.50);
        order.printReceipt();
    }
}

