class ProcessorCore {
    private int coreId;
    private boolean active = true;

    public ProcessorCore(int coreId) {
        this.coreId = coreId;
    }

    public void shutdown() {
        this.active = false;
        System.out.println("[Core-" + coreId + "] Safely powered down.");
    }
}

class Microprocessor {
    private String model;
    private ProcessorCore[] cores; // Composed internal hardware

    public Microprocessor(String model, int coreCount) {
        this.model = model;
        this.cores = new ProcessorCore[coreCount];
        // The processor creates its own cores
        for (int i = 0; i < coreCount; i++) {
            cores[i] = new ProcessorCore(i);
        }
    }

    // Cascading disposal of composed parts
    public void powerOff() {
        System.out.println("Shutting down processor: " + model);
        for (ProcessorCore core : cores) {
            core.shutdown();
        }
        System.out.println("All cores halted.");
    }
}

public class CascadingDemo {
    public static void main(String[] args) {
        Microprocessor cpu = new Microprocessor("Octa-Silicon 9", 4);
        cpu.powerOff();
    }
}

