import java.util.ArrayList;
import java.util.List;

class Room {
    private String name;
    private double areaSqFt;
    public Room(String name, double areaSqFt) {
        this.name = name;
        this.areaSqFt = areaSqFt;
    }
    public String getInfo() { return name + " (" + areaSqFt + " sq ft)"; }
}

class House {
    private String address;
    private List<Room> rooms = new ArrayList<>(); // Composed parts

    public House(String address) {
        this.address = address;
    }

    public void addRoom(String name, double areaSqFt) {
        rooms.add(new Room(name, areaSqFt));
    }

    public void displayBlueprint() {
        System.out.println("House at: " + address);
        for (Room r : rooms) {
            System.out.println(" - Room: " + r.getInfo());
        }
    }
}

