import java.util.ArrayList;
import java.util.List;

class DocumentPage {
    private int pageNum;
    private String textContent;

    public DocumentPage(int pageNum, String textContent) {
        this.pageNum = pageNum;
        this.textContent = textContent;
    }

    public int getWordCount() {
        if (textContent == null || textContent.trim().isEmpty()) return 0;
        return textContent.trim().split("\\s+").length;
    }

    public String getSnippet() {
        return "Page " + pageNum + " (" + getWordCount() + " words)";
    }
}

class Document {
    private String title;
    private List<DocumentPage> pages = new ArrayList<>();

    public Document(String title) {
        this.title = title;
    }

    public void addPage(String content) {
        pages.add(new DocumentPage(pages.size() + 1, content));
    }

    public void printDocumentStats() {
        System.out.println("Document: " + title + " [" + pages.size() + " pages]");
        int totalWords = 0;
        for (DocumentPage p : pages) {
            System.out.println(" > " + p.getSnippet());
            totalWords += p.getWordCount();
        }
        System.out.println("Total Words: " + totalWords);
    }
}

public class DocApp {
    public static void main(String[] args) {
        Document doc = new Document("OOP Design Manual");
        doc.addPage("Inheritance is powerful but easily misused");
        doc.addPage("Favor object composition over class inheritance");
        doc.printDocumentStats();
    }
}

