    private RobotBattery battery = new RobotBattery(); // Composed

    public Robot(String serialNumber) {
        this.serialNumber = serialNumber;
    }

    // BUG: Leaking private composed component reference!
    public RobotBattery getBattery() {
        return battery;
    }
}

public class EncapsulationBugApp {
    public static void main(String[] args) {
        Robot bot = new Robot("BOT-X1");
        // Instead of leaking getBattery(), bot should have charge() and getChargeLevel()
        bot.charge(10);
        System.out.println("Robot [" + bot.getSerialNumber() + "] Battery: " + bot.getChargeLevel() + "%");
    }
}

