import java.util.ArrayList;
import java.util.List;

class TransactionLog {
    private List<String> entries = new ArrayList<>();
    public void record(String action) {
        entries.add(action);
    }
    public void flush() {
        System.out.println("Flushing " + entries.size() + " audit log entries");
        entries.clear();
    }
}

class ConnectionPool {
    private int activeConnections;
    public void open() {
        activeConnections = 3;
        System.out.println("Opened 3 DB connections");
    }
    public void closeAll() {
        activeConnections = 0;
        System.out.println("Closed all DB connections");
    }
}

class DatabaseTransactionManager {
    private String txId;
    private TransactionLog log;
    private ConnectionPool pool;

    public DatabaseTransactionManager(String txId) {
        this.txId = txId;
        this.log = new TransactionLog();
        this.pool = new ConnectionPool();
    }

    public void begin() {
        System.out.println("=== Transaction " + txId + " BEGIN ===");
        pool.open();
    }

    public void executeOp(String op) {
        log.record(op);
    }

    public void commit() {
        System.out.println("Committing transaction " + txId);
        log.flush();
        pool.closeAll();
        System.out.println("=== Transaction " + txId + " END ===");
    }
}

public class TxApp {
    public static void main(String[] args) {
        DatabaseTransactionManager tm = new DatabaseTransactionManager("TX-770");
        tm.begin();
        tm.executeOp("INSERT User (Alice)");
        tm.executeOp("UPDATE Balance (Alice, 500)");
        tm.commit();
    }
}
